package main

import (
	"context"
	"testing
)

func TestHistoryHeavyAdmissionRejectsCanceledBeforeDetailWork(t *testing.T) {
	guard := newHistoryResourceAdmission(1)
	ctx, cancel := context.WithCancel(context.Background())
	cancel()
	if _, err := guard.acquire(ctx); err == nil {
		t.Fatal("expected canceled context rejection")
	}
}
